someSLHDASignatureBroken :: Base64 'UrlUnpadded T.Text
someSLHDASignatureBroken = B64URLT.encodeBase64Unpadded "Hello world => Expect a wrong size here"

someEncodedButBrokenUserSig :: ByteString
someEncodedButBrokenUserSig = T.encodeUtf8 "{\"sig\":\"I am completly broken signature\"}"


-- Simple Round Trip test => Encode then Parse and check equaliity
assertUserSimpleRoundTrip :: UserSig -> Assertion
assertUserSimpleRoundTrip usig = do
  let roundTripResult = A.eitherDecode $ J.encode usig

  case roundTripResult of
    Right val -> usig @=? val
    Left err -> assertFailure ("RounTrip failed for:" <> err)

-- Double Round Trip test => Encode then Parse and Encode again = check for equality between the 2 JSON encoded
assertUserSigEncodedRoundTrip :: UserSig -> Assertion
assertUserSigEncodedRoundTrip usig = do
  let firstEncoding = J.encode usig
  let secondEncoding = J.encode <$> (A.eitherDecode $ J.encode usig :: Either String UserSig)

  case secondEncoding of
    Right val -> firstEncoding @=? val
    Left err -> assertFailure ("RounTrip failed for:" <> err)

assertUserSigRoundTrip :: UserSig -> Assertion
assertUserSigRoundTrip usig = do
  assertUserSimpleRoundTrip usig
  assertUserSigEncodedRoundTrip usig

-- When parsing is supposed to fail
assertUserSigRoundTripFail :: UserSig -> Assertion
assertUserSigRoundTripFail usig = do
  let roundTripResult = A.eitherDecode $ J.encode usig :: Either String UserSig

  case roundTripResult of
    Right _ -> assertFailure "Parsing was supposed to fail here"
    Left _ -> return ()

assertUserInvalidSignature :: ByteString -> Assertion
assertUserInvalidSignature usigEncoded = do
  let decodedResult = A.eitherDecodeStrict usigEncoded  :: Either String UserSig

  case decodedResult of
    Right _ -> assertFailure "Parsing was supposed to fail here"
    Left err -> err @?= "Error in $: Invalid Signature"



tests :: TestTree
tests = testGroup "request-api-roundtrips"
          [
            testCase "WebAuthn RoundTrip"        (assertUserSigRoundTrip     $ WebAuthnSig someWebAuthnSignature)
          , testCase "ED25519 RoundTrip"         (assertUserSigRoundTrip     $ ED25519Sig  someEdDSASignature)
          , testCase "SLH-DSA RoundTrip"         (assertUserSigRoundTrip     $ SLHDSASig   someSLHDASignature)
          -- This test wrong signature sizes
          , testCase "ED25519 Roundtrip failure" (assertUserSigRoundTripFail $ ED25519Sig  someEdDSASignatureBroken)
          , testCase "SLH-DA Roundtrip failure"  (assertUserSigRoundTripFail $ SLHDSASig   someSLHDASignatureBroken)
          , testCase "Invalid Signature"         (assertUserInvalidSignature someEncodedButBrokenUserSig)
          ]
